\label{ex:atomic}

{Consider prices taking values $0.2,0.4,0.6,0.8$. If each price has probability $1/4$, then $a^-=0.4$, $a^+=0.6$, and $\Delta_F=0.2$. If instead these prices have probabilities $0.25,0.20,0.30,0.25$, respectively, the median lies inside the atom at $0.6$: now $a^-=a^+=0.6$ and $\Delta_F=0$.} Both distributions satisfy Definition~\ref{def:atomic-family} with $\mu=0.05$.

{Figure~\ref{fig:example-atomic} shows that the same support can yield either a positive median gap or no median gap, depending on the probability masses.}

\label{def:continuous-family}

{For $\beta\ge0$, $\varepsilon_0\in(0,1/4]$, and $\Delta\in[0,1)$, let $\mathcal F^{\mathrm{ac}}_{\beta,\Delta,\varepsilon_0}$ be the class of absolutely continuous distributions $F$ on $[0,1]$ with bounded density and median gap $\Delta_F=\Delta$, satisfying the following conditions. There exist constants $c_-,c_+>0$ and remainder functions $r_-,r_+$ such that, for every $0<q<\varepsilon_0$,}





{
\begin{align*}
 a_F^--F^{-1}(1/2-q)&=c_-q^{1/(\beta+1)}(1+r_-(q)), \\
 F^{-1}(1/2+q)-a_F^+&=c_+q^{1/(\beta+1)}(1+r_+(q)).
\end{align*}
}
The remainder functions satisfy $|r_\pm(q)|\le1/2$ and $r_\pm(q)\to0$ as $q\downarrow0$.

{When $\beta=0$, they additionally satisfy $|r_\pm(q)|\le Lq^\eta$ for some $L\ge0$ and $\eta>0$. The density bound, constants, and remainder functions may depend on $F$.}

\label{ex:no-gap}
With $\Delta=0$, let $F_{\beta,0}$ have density $f_{\beta,0}(p)=(\beta+1)2^\beta|p-1/2|^\beta$ for $0\le p\le1$. These give uniform, V-shaped, and quadratic examples at $\beta=0,1,2$ respectively. Their quantiles satisfy $F_{\beta,0}^{-1}(1/2\pm q)=1/2\pm(2q)^{1/(\beta+1)}/2$ for $0<q<1/2$.
Thus they satisfy Definition~\ref{def:continuous-family} with zero remainder. Figure~\ref{fig:example-no-gap} displays the densities and their quantile functions. The shaded band isolates the local median window.

\label{ex:positive-gap}
For $\Delta\in(0,1)$, put $a^\pm=(1\pm\Delta)/2$ and let $F_{\beta,\Delta}$ have density
\begin{align}
 f_{\beta,\Delta}(p)=\frac{(\beta+1)2^\beta}{(1-\Delta)^{\beta+1}}
 \begin{cases}(a^--p)^\beta,&0\le p<a^-,\\
     0,&a^-<p<a^+, \\
 (p-a^+)^\beta,&a^+<p\le1.\\
 \end{cases}
 \label{eq:canonical-gap-density}
\end{align}
These examples belong to Definition~\ref{def:continuous-family}, with $r_\pm=0$, $c_-=c_+=(1-\Delta)2^{-\beta/(\beta+1)}$, and $M=(\beta+1)/(1-\Delta)$. For $\beta>0$ the density vanishes at the gap edges. Equation~\eqref{eq:canonical-gap-density} also supplies the explicit instances for our lower bound discussed in Theorem \ref{lb:thm-positive-gap}. The quantiles satisfy $F_{\beta,\Delta}^{-1}(1/2\pm q)=a^\pm\pm(1-\Delta)(2q)^{1/(\beta+1)}/2$ for $0<q<1/2$.
Figure~\ref{fig:example-positive-gap} shows the resulting jump at the median for $\Delta=0.2$.

\label{prop:interior-transfer}
Fix $\eta>0$, let $T\ge2$, and assume $y_0\wedge(B-y_0)\ge\eta T$.
\begin{enumerate}[label=$(\alph*)$]
    \item Fix $\mu\in(0,1/2]$ and $\Delta\in[0,1]$. For every distribution $F\in\mathcal F^{\rm at}_{\mu,\Delta}$, there exists a constant $C=C(F,\eta)<\infty$ such that $\operatorname{Reg}(\pi^{\textup{\textsf{CwG}}};B,T,y_0)\le C$.
    \item Fix $\beta\ge0$, $\varepsilon_0\in(0,1/4]$, and let $\Delta=0$. For every distribution $F\in\mathcal F^{\rm ac}_{\beta,\Delta,\varepsilon_0}$, there exists a constant $C=C(F,\eta)<\infty$ such that
    \begin{align*}
        \operatorname{Reg}(\pi^{\textup{\textsf{CwG}}};B,T,y_0)
        \le C\log T\,\mathbbm{1}\{\beta=0\}
        +CT^{\beta/(2\beta+2)}\,\mathbbm{1}\{\beta>0\}.
    \end{align*}
    \item Fix $\beta\ge0$, $\varepsilon_0\in(0,1/4]$, and $\Delta\in(0,1)$. For every distribution $F\in\mathcal F^{\rm ac}_{\beta,\Delta,\varepsilon_0}$, there exists a constant $C=C(F,\eta)<\infty$ such that
    \begin{align*}
        \operatorname{Reg}(\pi^{\textup{\textsf{CwG}}};B,T,y_0)
        \le C\log^2 T\,\mathbbm{1}\{\beta=0\}
        +CT^{\beta/(2\beta+2)}(\log T)^{(\beta+2)/(2\beta+2)}
          \,\mathbbm{1}\{\beta>0\}.
    \end{align*}
\end{enumerate}

\label{prop:main-concavity}
Fix a terminal target $y_0$ and a decision epoch $t$.
\begin{enumerate}[label=$(\alph*)$]
    \item For every fixed future price sequence $\mathbf p_{>t}$,
    the function $V_{t+1}^{\mathsf{hs}}(\cdot;\mathbf p_{>t})$ is
    discretely concave on $\mathcal Y_{t+1}$. Its expectation and
    its empirical average are also discretely
    concave. Consequently, the realized, expected, and sample-average
    marginal values are nonincreasing in inventory.
    \item At every inventory $y$ where all three actions are feasible,
    \textup{\textsf{STARS}{}} uses the rule
    \begin{align*}
     x_t=\begin{cases}
     +1,&p_t<\widehat\lambda_{t+1}(y+1),\\
     0,&\widehat\lambda_{t+1}(y+1)\le p_t\le\widehat\lambda_{t+1}(y),\\
     -1,&p_t>\widehat\lambda_{t+1}(y).
     \end{cases}
    \end{align*}
\end{enumerate}

\label{prop:main-decomposition}
Fix $T,B$, an initial and terminal inventory $y_0$, and a feasible
online policy $\pi$.
\begin{enumerate}[label=$(\alph*)$]
\item For every realized price sequence and policy trajectory,
\begin{align*}
 V_1^{\mathsf{hs}}(B,T,y_0;\mathbf p)
 -\sum_{t=1}^T(-p_tx_t^\pi)
 =\sum_{t=1}^T
 \partial R_t(y_{t-1}^\pi,x_t^\pi;\mathbf p_{\ge t}).
\end{align*}
\item Consequently,
\begin{align*}
 \operatorname{Reg}(\pi;B,T,y_0)
 =\sum_{t=1}^T\mathbb E\left[
 \mathbb E\left[
 \partial R_t(y_{t-1}^\pi,x_t^\pi;\mathbf p_{\ge t})
 \mid\mathcal F_{t-1}
 \right]\right].
\end{align*}
\end{enumerate}

\label{lb:lem-accounting}
Let $\pi$ be a feasible cyclic policy and $\pi^{\mathsf{hs}}$ a
hindsight-optimal feasible policy. Put
$M_t:=\max_{0\leq s\leq t}(-S_s)^+$ and define the correction cost
\begin{align}
    C_T(\pi)
    :=\sum_{t:\xi_t=+1}W_t\ell_t
      +\sum_{t:\xi_t=-1}(\Delta+Z_t)u_t.
    \label{lb:eq-correction-cost}
\end{align}
The following statements hold pathwise.
\begin{enumerate}[label=$(\alph*)$]
\item The inventory satisfies
\begin{align}
    y_t=S_t+U_t-L_t.
    \label{lb:eq-state-ledger}
\end{align}
\item The upper-side correction count satisfies $U_T\geq M_T$.
\item The marginal compensations satisfy
\begin{align}
    \sum_{t=1}^T
       \partial R_t(y_{t-1}^\pi,x_t^\pi;\mathbf p_{\geq t})
    =R_T(\pi^{\mathsf{hs}};0)-R_T(\pi;0)
    =C_T(\pi)-C_T(\pi^{\mathsf{hs}}).
    \label{lb:eq-two-accountings}
\end{align}
\end{enumerate}

\label{lb:lem-deadline-sum}
Fix $\kappa\geq1$, put $a:=1/\kappa\in(0,1]$, and define
\begin{align*}
    \Phi_\kappa(T)
    :=\log T\mathbbm{1}\{\kappa=1\}
      +T^{(\kappa-1)/(2\kappa)}\mathbbm{1}\{\kappa>1\}.
\end{align*}
There exists a constant $C_\kappa<\infty$, depending only on $\kappa$,
such that $\mathbb E[\sum_{y:\sigma_y\leq T}(y/(\sigma_y+1))^a]
\leq C_\kappa\Phi_\kappa(T)$ for every $T\geq2$.

\label{ce:accounting}
For a price vector with no observation equal to $1/2$, set
$x_t^*=\mathbf 1\{p_t<1/2\}-\mathbf 1\{p_t>1/2\}$ and
$H_T=\sum_{t=1}^T|p_t-1/2|$.
For any feasible cyclic trading path $\pi$, define its premium by
\begin{align*}
 G_T(\pi)&=\sum_{t=1}^T g_t(x_t^\pi),&
 g_t(x)&=|p_t-1/2|+(p_t-1/2)x.
\end{align*}
Then the following statements hold.
\begin{enumerate}[label=$(\alph*)$]
\item For every $x\in\{-1,0,1\}$, $0\le g_t(x)\le1$.
\item The realized reward satisfies $R_T(\pi;y_0)=H_T-G_T(\pi)$.
\item For any other feasible path $\pi^{\rm cmp}$, including one that
uses the entire price sequence,
\begin{align*}
 \operatorname{Reg}(\pi;B,T,y_0)&\le\mathbb E G_T(\pi),\\
 \operatorname{Reg}(\pi;B,T,y_0)&\ge\mathbb E G_T(\pi)-\mathbb E G_T(\pi^{\rm cmp})
\end{align*}
\end{enumerate}

\label{prop:static-interior}
Fix $\eta>0$ and assume $y_0\wedge(B-y_0)\ge\eta T$. Let prices be i.i.d.\
on $[0,1]$, and let $V^{\mathrm{stat}}(\mathbf p)$ be the best realized
profit with unit trades and $\sum_tx_t=0$, but without intermediate
storage constraints. Then
\begin{align*}
 0\le\mathbb E[V^{\mathrm{stat}}(\mathbf p)-V_1^{\mathsf{hs}}(B,T,y_0;\mathbf p)]
 \le 2T^2e^{-\eta^2T/2}.
\end{align*}

\label{lem:main-marginal-range}
Fix a terminal target, a future sequence in $[0,1]$, and adjacent feasible
continuation states $j-1,j$. Then $0\le\Delta V^{\mathsf{hs}}(j)\le1$.

\label{prop:main-nonvanishing}
Assume independent uniform prices on $[0,1]$ and terminal inventory
zero. Fix $B\ge1$ and any feasible online policy $\pi$. For every
$t<T$,
\begin{align*}
 \mathbb E[\partial R_t(y_{t-1}^\pi,x_t^\pi;\mathbf p_{\ge t})
 \mid\mathcal F_{t-1}]\ge\frac1{384}\mathbf 1\{y_{t-1}^\pi=0\}.
\end{align*}

\label{lem:stars-concavity}\label{lem:stars-queue}
Fix a future price vector in $[0,1]^\tau$ and a capacity $B$.
\begin{enumerate}[label=$(\alph*)$]
\item $V_\tau^B$ is discretely concave, its real marginals form a
decreasing list, and each marginal is one of the future prices.
Thus the marginals lie in $[0,1]$, and $\mathbb E V_\tau^B$ is also concave.
\item Prepending price $p$ updates every new real marginal by
\begin{align}
 \widetilde{\Delta V}(y)=\Delta V_\tau^B(y+1)\vee\bigl(p\wedge\Delta V_\tau^B(y-1)\bigr).
 \label{eq:stars-minmax}
\end{align}
For this formula only, use ordering conventions $\Delta V_\tau^B(y)=+\infty$
for $y\le0$ and $\Delta V_\tau^B(y)=-\infty$ beyond the old domain. They are
not random values whose expectations are taken.
\end{enumerate}

\label{prop:main-local-compensation}
Condition on $\mathcal F_{t-1}$, let $y=y_{t-1}^{\pi^K}$, and
suppose the hold action is feasible at $y$.
Use the mean thresholds $b^\circ$ and $s^\circ$ defined above,
and let $K=K_t\ge1$.
\begin{enumerate}[label=$(\alph*)$]
\item For a finite atomic law with support $A_1<\cdots<A_m$ and
masses $w_1,\ldots,w_m$, the mean-threshold rule $\pi^\circ$
has conditional expected compensation
\begin{align}
 \mathbb E[\partial R_t(y,x_t^\circ(y,p_t);\mathbf p_{\ge t})
                                 \mid\mathcal F_{t-1}] &=\sum_{i=1}^m w_i\Big\{
    \big(\mathbb E[(b^{\mathsf{hs}}-A_i)^+\mid\mathcal F_{t-1}]
           \wedge\mathbb E[(A_i-b^{\mathsf{hs}})^+\mid\mathcal F_{t-1}]\big) \notag\\
   &\qquad + \big(\mathbb E[(s^{\mathsf{hs}}-A_i)^+\mid\mathcal F_{t-1}]
           \wedge\mathbb E[(A_i-s^{\mathsf{hs}})^+\mid\mathcal F_{t-1}]\big)
                    \Big\}.
 \label{eq:main-atomic-hinge}
\end{align}
With $K$ simulated futures, \textup{\textsf{STARS}{}} satisfies
\begin{align*}
 \mathbb E[\partial R_t(y,x_t^K(y,p_t;\zeta_t);\mathbf p_{\ge t})
                                     \mid\mathcal F_{t-1}] \le2\mathbb E[\partial R_t(y,x_t^\circ(y,p_t);\mathbf p_{\ge t})
                                     \mid\mathcal F_{t-1}]
                +\frac{40}{3eK}.
\end{align*}
\item For uniform prices on $[0,1]$, the expected compensation of
\textup{\textsf{STARS}{}} is exactly
\begin{align*}
 \mathbb E[\partial R_t(y,x_t^K;\mathbf p_{\ge t})\mid\mathcal F_{t-1}] =\frac{1+1/K}{2}
 \left\{\operatorname{Var}(b^{\mathsf{hs}}\mid\mathcal F_{t-1})
             +\operatorname{Var}(s^{\mathsf{hs}}\mid\mathcal F_{t-1})\right\}.
\end{align*}
\item Fix $\rho\in(0,1)$, let $B=\lceil\rho T\rceil$, and take
$F\in\mathcal F^{\mathrm{ac}}_{\beta,\Delta,\varepsilon_0}$
from Definition~\ref{def:continuous-family}, allowing $\Delta=0$.
Set $\alpha=1/(\beta+1)$ and $\tau_t=T-t+1$. There are constants
$C,c_\rho>0$, depending on $F,\rho$ but not $T$, such that for
$K_t\ge\tau_t^2$,
\begin{align}
 \mathbb E[\partial R_t(y,x_t^K;\mathbf p_{\ge t})\mid\mathcal F_{t-1}] \le C\left\{ \left(\frac{1}{y + 1} \right)^{1 + \alpha}
   +\left(\frac{y+1}{\tau_t}\right)^{1+\alpha}
   +\tau_t^{-\frac{1+\alpha}{2}}
   +\varepsilon_T+\mathbbm{1}\Big\{y>\frac{B}{2}\Big\}\right\},
 \label{eq:main-continuous-charge}
\end{align}
where $\varepsilon_T=CT^2e^{-c_\rho T}$. The same bound holds for the
reference action $x_t^\circ(y,p_t)$.
\end{enumerate}

\label{lem:stars-hitting}
Fix integers $1\le y\le \tau$.
\begin{enumerate}[label=$(\alph*)$]
\item For every price level $u$,
$\mathbb P(\Delta V_\tau(y)>u)=\mathbb P_{1-F(u)}(\sigma_y\le \tau)$.
\item For $0<a<1/2$,
\begin{align}
 \mathbb P_a(\sigma_y\le \tau)
 &=\left(\frac a{1-a}\right)^y\mathbb P_{1-a}(\sigma_y\le \tau)
 \le\left(\frac a{1-a}\right)^y.
 \label{eq:stars-likelihood}
\end{align}
\end{enumerate}

\label{lem:stars-fair}
Fix integers $\tau,y\ge1$.
\begin{enumerate}[label=$(\alph*)$]
\item With absolute comparison constants $c,C>0$,
\begin{align*}
 \mathbb P_{1/2}(\sigma_y>\tau)&=\mathbb P(-y\le S_\tau<y)
 \asymp \frac{y}{\sqrt{\tau+1}}\wedge1.
\end{align*}
\item For every fixed sign probability and $x\ge0$,
\begin{align}
 \mathbb P\left(\max_{j\le \tau}(S_j-\mathbb E S_j)\ge x\right)
 &\le e^{-x^2/(2\tau)}.\label{eq:stars-hoeffding}
\end{align}
The same inequality holds for the negative centered walk.
\item If $a>1/2$ and $y\le(2a-1)\tau$, then
\begin{align}
 \mathbb P_a(\sigma_y>\tau)
 \le e^{-((2a-1)\tau-y)^2/(2\tau)}.\label{eq:stars-failure}
\end{align}
\end{enumerate}

\label{lem:stars-uniformmoments}
Fix $h>0$. There is a constant $C_h<\infty$ such that, for all
$\tau\ge1$ and $1\le y\le \tau$,
\begin{align*}
 \mathbb E|d_\tau(y)-1/2|^h\le C_h\{y^{-h}+(y/(\tau+1))^h+(\tau+1)^{-h/2}\}.
\end{align*}
For $d_\tau^B(y)$ at $y\le B/2+1$, add $C_h\varepsilon_T$.

\label{thm:stars-continuous}
Fix $\rho\in(0,1)$ and an atomless distribution $F$ with bounded
density and the edge definitions and regularity assumptions above,
including \eqref{eq:stars-sc-regularity} and the quantitative remainder
when $\alpha=1$. Let $\alpha\in(0,1]$, $y_0=y_T=0$, and
$B=\lceil\rho T\rceil$. There is a constant $C=C(F,\rho)<\infty$,
which may depend on the regularity moduli but not on $T$, such that
the reference rule $\pi^\circ$ satisfies the following bounds.
\begin{enumerate}[label=$(\alph*)$]
\item If $\Delta=0$, then
\begin{align*}
 \operatorname{Reg}_T\le C\log^2 T\mathbf 1\{\alpha=1\}
          +CT^{(1-\alpha)/2}\mathbf 1\{0<\alpha<1\}.
\end{align*}
\item If the fixed gap satisfies $\Delta>0$, then
\begin{align*}
 \operatorname{Reg}_T\le CT^{1/4}\log T\mathbf 1\{\alpha=1\}
          +CT^{1/[2(1+\alpha)]}\mathbf 1\{0<\alpha<1\}.
\end{align*}
\end{enumerate}
No uniform constant
over all distributions satisfying only the qualitative asymptotics is
asserted. Throughout this appendix, $(y_t,x_t)$ denotes the
reference trajectory. The finite-scenario algorithm is handled by
Appendix~\ref{app:stars-sampling}.

\label{lem:stars-sc-accounting}
Consider a contiguous block of at most $\bar\tau$ decision epochs. Suppose every
threshold on edges $1,\ldots,J$ is real throughout the block and
$\gamma_{\tau_t-1}^B(y)\ge b_y\ge1/2$ at each epoch $t$ in the
block, where $b_y<1$ are fixed numbers.
Fix a nonnegative decreasing $f$, set $\pi_0=1$ and
$\pi_j=\prod_{i=1}^j b_i/(1-b_i)$, and define its weighted mean by
$\bar f=\sum_{j=0}^J\pi_j f(j)/\sum_{j=0}^J\pi_j$.
Set $G_J=0$ and, for $0\le j<J$, set
\begin{align}
 G_j=\frac{\sum_{i=0}^j\pi_i(f(i)-\bar f)}{\pi_j b_{j+1}},
 \qquad
 \Phi(y)=\sum_{j=0}^{(y\wedge J)-1}G_j.
 \label{eq:stars-sc-accounting-function}
\end{align}
Conditionally on any history at the start of the block,
\begin{align*}
 \mathbb E\sum_{t\text{ in block}}f(y_{t-1})\le \bar\tau\bar f+\Phi(J).
\end{align*}

\label{prop:stars-continuous-sampling}
Fix an $M$-Lipschitz distribution $F$. Let $K_t\ge1$ be chosen
from the past before observing $p_t$, and use $K_t$ shared fresh i.i.d.\
futures independent of the current price and actual future. Then
\begin{align*}
 \operatorname{Reg}_T(\pi^K)
 \le\operatorname{Reg}_T(\pi^\circ)+M\mathbb E\sum_{t=1}^{T-1} K_t^{-1/2}.
\end{align*}
In particular $K_t\ge(T-t+1)^2$ adds at most $M\log T$,
preserving all the continuous-class rates.
